import{_t as e,it as t,n,rt as r}from"./chunks/framework.D2cFUyj2.js";var i=JSON.parse(`{"title":"Ejemplos de plugins","description":"","frontmatter":{},"headers":[{"level":2,"title":"1. CoreExtensions —— Acciones, menús Shell y Panel rápido","slug":"_1-coreextensions-——-acciones-menus-shell-y-panel-rapido","link":"#_1-coreextensions-——-acciones-menus-shell-y-panel-rapido","children":[{"level":3,"title":"Puntos clave de implementación","slug":"puntos-clave-de-implementacion","link":"#puntos-clave-de-implementacion","children":[]}]},{"level":2,"title":"2. PinyinAlias —— Motor de transliteración para caracteres no ASCII","slug":"_2-pinyinalias-——-motor-de-transliteracion-para-caracteres-no-ascii","link":"#_2-pinyinalias-——-motor-de-transliteracion-para-caracteres-no-ascii","children":[{"level":3,"title":"Puntos clave de implementación","slug":"puntos-clave-de-implementacion-1","link":"#puntos-clave-de-implementacion-1","children":[]}]},{"level":2,"title":"3. FlowLauncherBridge —— Compatibilidad entre ecosistemas y entornos aislados","slug":"_3-flowlauncherbridge-——-compatibilidad-entre-ecosistemas-y-entornos-aislados","link":"#_3-flowlauncherbridge-——-compatibilidad-entre-ecosistemas-y-entornos-aislados","children":[{"level":3,"title":"Puntos clave de implementación","slug":"puntos-clave-de-implementacion-2","link":"#puntos-clave-de-implementacion-2","children":[]}]},{"level":2,"title":"4. FileUnlocker —— Acción para liberar la ocupación de archivos","slug":"_4-fileunlocker-——-accion-para-liberar-la-ocupacion-de-archivos","link":"#_4-fileunlocker-——-accion-para-liberar-la-ocupacion-de-archivos","children":[{"level":3,"title":"Puntos clave de implementación","slug":"puntos-clave-de-implementacion-3","link":"#puntos-clave-de-implementacion-3","children":[]}]}],"relativePath":"es-ES/dev-guide/examples.md","filePath":"es-ES/dev-guide/examples.md","lastUpdated":1791112464000}`),a={name:`es-ES/dev-guide/examples.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="ejemplos-de-plugins" tabindex="-1">Ejemplos de plugins <a class="header-anchor" href="#ejemplos-de-plugins" aria-label="Permalink to “Ejemplos de plugins”">​</a></h1><p>Para ayudar a los desarrolladores a comprender cómo interactúan las interfaces de <code>Lertaro.PluginSdk</code>, este capítulo analiza cuatro plugins representativos incluidos en el repositorio de Lertaro.</p><h2 id="_1-coreextensions-——-acciones-menus-shell-y-panel-rapido" tabindex="-1">1. CoreExtensions —— Acciones, menús Shell y Panel rápido <a class="header-anchor" href="#_1-coreextensions-——-acciones-menus-shell-y-panel-rapido" aria-label="Permalink to “1. CoreExtensions —— Acciones, menús Shell y Panel rápido”">​</a></h2><p>El plugin <code>CoreExtensions</code> constituye el paquete de extensiones principal de Lertaro e implementa <code>IPlugin</code>, <code>IActionProvider</code>, <code>IConfigurable</code> y varios proveedores secundarios.</p><h3 id="puntos-clave-de-implementacion" tabindex="-1">Puntos clave de implementación <a class="header-anchor" href="#puntos-clave-de-implementacion" aria-label="Permalink to “Puntos clave de implementación”">​</a></h3><ul><li><strong>Acciones estáticas (<code>IActionProvider.GetActions()</code>)</strong>: Registra acciones esenciales sobre archivos, como abrir y ubicar elementos, copiar rutas y archivos, añadir a Favoritos, cambiar nombres, usar la consola, eliminar y ejecutar como Administrador.</li><li><strong>Integración con menús Shell de Windows (<code>IDynamicActionProvider</code>)</strong>: Se comunica con las interfaces COM del Shell mediante <code>ShellMenuActionProvider</code>, renderizando menús contextuales completos (con submenús como &quot;Enviar a&quot;, 7-Zip, VS Code) dentro del menú <code>Ctrl+O</code>.</li><li><strong>Formularios de configuración por esquemas (<code>IConfigurable</code>)</strong>: Define esquemas con grupos anidados (<code>Group</code>), listas de cadenas (<code>StringList</code>) y asignación de atajos (<code>Hotkey</code>), generando formularios nativos en Configuración sin escribir XAML.</li><li><strong>Pestañas para el Panel rápido (<code>IQuickPanelTabProvider</code>)</strong>: <ul><li><code>FavoritesTabProvider</code> / <code>HistoryTabProvider</code>: sirven los favoritos y el historial que el anfitrión ya tiene cargados, en lugar de volver a leerlos del disco; la consulta del historial se despacha fuera del hilo de interfaz (<code>Task.Run</code>), así que invocar el panel nunca espera por ella.</li><li><code>WindowsRecentTabProvider</code>: Recorre la carpeta <code>Recent</code> en segundo plano, resuelve accesos directos COM y añade <code>Metadata.Modified</code> para su ordenación.</li><li><code>LastDirectoryTabProvider</code> / <code>RecentFilesTabProvider</code>: Consulta directamente <a href="./sdk/services.html"><code>ExplorerPathService</code></a> y <code>RecentFilesService</code> del anfitrión.</li></ul></li></ul><h2 id="_2-pinyinalias-——-motor-de-transliteracion-para-caracteres-no-ascii" tabindex="-1">2. PinyinAlias —— Motor de transliteración para caracteres no ASCII <a class="header-anchor" href="#_2-pinyinalias-——-motor-de-transliteracion-para-caracteres-no-ascii" aria-label="Permalink to “2. PinyinAlias —— Motor de transliteración para caracteres no ASCII”">​</a></h2><p><code>PinyinAlias</code> proporciona búsqueda por pinyin completo y siglas para nombres de archivos en chino, implementando <code>IAliasProvider</code> e <code>ITranslationProvider</code>.</p><h3 id="puntos-clave-de-implementacion-1" tabindex="-1">Puntos clave de implementación <a class="header-anchor" href="#puntos-clave-de-implementacion-1" aria-label="Permalink to “Puntos clave de implementación”">​</a></h3><ul><li><strong>Límites de alfabetos (<code>InputRanges</code> / <code>OutputRanges</code>)</strong>: Declara un único rango ideográfico CJK (U+3007–U+9FFD) como límite de entrada y <code>a</code>–<code>z</code> en minúsculas como salida, permitiendo dividir consultas mixtas en segmentos literales y de alias.</li><li><strong>Comprobación previa rápida (<code>CanHandle(text)</code>)</strong>: Detecta si el texto contiene caracteres chinos antes de generar alias, devolviendo <code>false</code> inmediatamente para cadenas en inglés.</li><li><strong>Combinaciones polifónicas (<code>GetAliases(text)</code>)</strong>: Construye un mapa silábico y genera combinaciones unidas por <code>|</code> (hasta un máximo de 32 para evitar saturación), permitiendo búsquedas paralelas.</li><li><strong>Localización incrustada y caché segura</strong>: Traduce el nombre del plugin mediante <code>ITranslationProvider</code> y almacena los JSON analizados en un diccionario protegido con <code>lock</code>.</li></ul><h2 id="_3-flowlauncherbridge-——-compatibilidad-entre-ecosistemas-y-entornos-aislados" tabindex="-1">3. FlowLauncherBridge —— Compatibilidad entre ecosistemas y entornos aislados <a class="header-anchor" href="#_3-flowlauncherbridge-——-compatibilidad-entre-ecosistemas-y-entornos-aislados" aria-label="Permalink to “3. FlowLauncherBridge —— Compatibilidad entre ecosistemas y entornos aislados”">​</a></h2><p>El plugin <code>FlowLauncherBridge</code> demuestra la creación de un sistema de puente a gran escala para integrar los ecosistemas externos de la comunidad en Lertaro.</p><h3 id="puntos-clave-de-implementacion-2" tabindex="-1">Puntos clave de implementación <a class="header-anchor" href="#puntos-clave-de-implementacion-2" aria-label="Permalink to “Puntos clave de implementación”">​</a></h3><ul><li><strong>Puente multiproceso y multilenguaje</strong>: Ejecuta plugins escritos en C# (.NET), Python 3.12, Node.js v20 LTS y binarios <code>.exe</code>.</li><li><strong>Entornos autónomos aislados</strong>: Despliega los entornos aislados de Python y Node.js bajo el <strong>directorio de datos compartido</strong> de Lertaro (<code>SharedDataDirectory\\FlowData\\PythonEmbeded-{arch}</code>), no en la carpeta de datos de cada usuario. Cada plugin habla con su intérprete a través de <strong>la entrada/salida estándar redirigida</strong> que transporta JSON-RPC: no hay tubería con nombre y nunca se toca la variable PATH del sistema.</li><li><strong>Formularios dinámicos y vistas previas en WebView2</strong>: Asigna formularios <code>SettingsTemplate.yaml</code>/<code>.json</code> a <code>PluginConfigSchema</code> y renderiza tarjetas interactivas (diccionarios, tiempo, etc.) dentro de QuickLook.</li></ul><h2 id="_4-fileunlocker-——-accion-para-liberar-la-ocupacion-de-archivos" tabindex="-1">4. FileUnlocker —— Acción para liberar la ocupación de archivos <a class="header-anchor" href="#_4-fileunlocker-——-accion-para-liberar-la-ocupacion-de-archivos" aria-label="Permalink to “4. FileUnlocker —— Acción para liberar la ocupación de archivos”">​</a></h2><p><code>FileUnlocker</code> muestra un plugin de acción especializada que consulta la ocupación de archivos mediante Windows Restart Manager y solicita su liberación.</p><h3 id="puntos-clave-de-implementacion-3" tabindex="-1">Puntos clave de implementación <a class="header-anchor" href="#puntos-clave-de-implementacion-3" aria-label="Permalink to “Puntos clave de implementación”">​</a></h3><ul><li><strong>Restricción de selección única</strong>: Solo ofrece la acción para un archivo existente seleccionado, evitando solicitudes ambiguas sobre carpetas o selecciones múltiples.</li><li><strong>Información de procesos</strong>: Muestra el nombre, PID y ruta del ejecutable de cada proceso que usa el archivo, con una opción de actualización para los cambios de estado.</li><li><strong>Liberación mediante solicitud</strong>: Solicita a los procesos implicados que liberen el archivo y desactiva el botón si no se detecta ningún proceso o hay una operación en curso.</li><li><strong>Marco de ventana del anfitrión</strong>: Aloja la vista WPF en el diálogo <code>PluginWindow</code> adaptado al tema del SDK, sin duplicar en el plugin la gestión del tema, DPI, barra de tareas o Alt+Tab.</li></ul>`,18)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};